def calculate_min_diff(M):
    # Set S = {M, M+1, M+2, M+3}
    s = [M, M+1, M+2, M+3]

    # There are 3 ways to partition into two pairs:
    # 1. {M, M+1} and {M+2, M+3}
    # 2. {M, M+2} and {M+1, M+3}
    # 3. {M, M+3} and {M+1, M+2}

    min_diff = float('inf')

    # Helper function to calculate ratio difference for a partition {s_a, s_b} vs {s_c, s_d}
    def check_partition(sa, sb, sc, sd):
        diffs = []
        # Check all 4 ratio assignments
        diffs.append(abs(sa/sb - sc/sd))
        diffs.append(abs(sa/sb - sd/sc))
        diffs.append(abs(sb/sa - sc/sd))
        diffs.append(abs(sb/sa - sd/sc))
        return min(diffs)

    # Partition 1: {M, M+1} vs {M+2, M+3}
    min_diff = min(min_diff, check_partition(M, M+1, M+2, M+3))

    # Partition 2: {M, M+2} vs {M+1, M+3}
    min_diff = min(min_diff, check_partition(M, M+2, M+1, M+3))

    # Partition 3: {M, M+3} vs {M+1, M+2}
    min_diff = min(min_diff, check_partition(M, M+3, M+1, M+2))

    return min_diff

# Test for increasing M
